import type { ShareLink } from '@app/contract'
import { ExpiryPicker } from './ExpiryPicker'

export function ShareButton({ link }: { link: ShareLink }) {
  const url = `${location.origin}/share/${link.token}`
  return <><ExpiryPicker onChange={() => {}} /><button onClick={() => navigator.clipboard.writeText(url)}>Copy link (valid until {link.expiresAt})</button></>
}

head_files.apps/web/src/share/Button.test.tsx:
import { ShareButton } from './Button'
test('copies the share link', async () => {
  render(<ShareButton link={{ token: 't1', scheduleId: 's1', expiresAt: '2026-12-01' }} />)
  await click(screen.getByRole('button'))
  expect(navigator.clipboard.writeText).toHaveBeenCalledWith(expect.stringContaining('/share/t1'))
})

